kp-hc-http.codeExample:
# Go HTTP 健康检查实现
http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
    w.WriteHeader(http.StatusOK)
    w.Write([]byte("ok"))
})
http.HandleFunc("/readyz", func(w http.ResponseWriter, r *http.Request) {
    if db.Ping() != nil {
        w.WriteHeader(503)
        return
    }
    w.WriteHeader(200)
})

kp-hc-deep.codeExample:
# Go 深度健康检查
func deepCheck(w http.ResponseWriter, r *http.Request) {
    ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
    defer cancel()
    status := 200
    // DB 连接池检查 (2s超时)
    if db.PingContext(ctx) != nil {
        status = 503
    }
    // Redis 检查 (1s超时)
    if redis.Ping(ctx).Err() != nil {
        status = 503
    }
    w.WriteHeader(status)
}

kp-wd-heartbeat.codeExample:
# Prometheus 心跳检测
# 应用每10s推送心跳
gauge := prometheus.NewGauge(prometheus.GaugeOpts{
  Name: "app_heartbeat_timestamp",
})
go func() {
  for {
    gauge.Set(float64(time.Now().Unix()))
    time.Sleep(10 * time.Second)
  }
}()
# 告警规则：30s 无心跳
- alert: HeartbeatMissing
  expr: time() - app_heartbeat_timestamp > 30

kp-wd-fencing.codeExample:
# etcd 分布式锁（防脑裂）
lease = etcd.lease(ttl=10)  # 10秒TTL
lock = etcd.lock(
  name="leader-election",
  lease=lease
)
# 主节点定期续约
go func() {
  for {
    lease.keep_alive()
    time.Sleep(3 * time.Second)
  }
}()
# 主节点宕机→TTL过期→锁自动释放→新主选举

kp-wd-coroutine.codeExample:
# Go 协程看门狗
go func() {
    defer func() {
        if r := recover(); r != nil {
            log.Printf("goroutine panic: %v", r)
            metrics.PanicCounter.Inc()
        }
    }()
    for {
        select {
        case <-ctx.Done():
            return  # context 超时退出
        case task := <-queue:
            process(task)
        }
    }
}()
# goroutine 数量监控
runtime.NumGoroutine() > 1000 → alert

